import test from 'node:test';
import assert from 'node:assert/strict';
globalThis.localStorage={getItem:()=>null,setItem:()=>{}};
const {useDemo}=await import('../src/stores/demo.js');const store=useDemo();
test('office scope hides exported snapshots, case/evidence/report rows from other offices',()=>{store.reset();store.signIn('u-admin');const e=store.state.events.find(e=>e.id==='e-003');store.recordExport({name:'All offices',snapshot:{events:[e],rows:[{Reference:e.ref}],metadata:{},sections:[]},selection:{}});const u=store.state.users.find(u=>u.id==='u-enforcement');u.scope='office';u.officeId='MRO-VII';store.signIn(u.id);assert.equal(store.visibleRecords('cases').some(c=>c.id==='case-001'),false);assert.equal(store.visibleRecords('evidence').some(c=>c.id==='doc-002'),false);assert.equal(store.visibleRecords('exports').length,0);const target=store.visibleEvents.value[0];assert.throws(()=>store.update('cases','case-001',{eventId:target.id}));});
test('discard draft detaches unsubmitted evidence and never reuses incident references',()=>{store.reset();store.signIn('u-reporter');const a=store.saveEvent({...store.newEvent(),summary:'A'});const b=store.saveEvent({...store.newEvent(),summary:'B'});const doc=store.add('evidence',{eventId:a.id,name:'Draft source',uploadedBy:'u-reporter'});store.remove('events',a.id);assert.equal(store.state.evidence.find(d=>d.id===doc.id).eventId,null);const c=store.saveEvent({...store.newEvent(),summary:'C'});assert.notEqual(c.ref,b.ref);});
test('storage capacity failure is surfaced while in-memory records remain usable',()=>{store.reset();const old=globalThis.localStorage.setItem;globalThis.localStorage.setItem=()=>{throw Error('Quota exceeded')};try{assert.equal(store.persist(),false);assert.match(store.state.persistenceError,/storage|saved|capacity/i);assert.ok(store.state.events.length>0)}finally{globalThis.localStorage.setItem=old;store.persist()}});
test('archived snapshots remain available after live records are removed and still obey office scope',()=>{store.reset();store.signIn('u-admin');const event=store.state.events.find(e=>e.id==='e-003');const saved=store.recordExport({name:'Archive',snapshot:{events:[JSON.parse(JSON.stringify(event))],rows:[{Reference:event.ref}],metadata:{},sections:[]}});store.state.events=store.state.events.filter(e=>e.id!==event.id);assert.ok(store.visibleRecords('exports').some(r=>r.id===saved.id));const u=store.state.users.find(u=>u.id==='u-enforcement');u.scope='office';u.officeId='MRO-VII';store.signIn(u.id);assert.equal(store.visibleRecords('exports').some(r=>r.id===saved.id),false)});
